CREATE TABLE "Clinic" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"city" TEXT NOT NULL,"address" TEXT NOT NULL,"description" TEXT NOT NULL,"timezone" TEXT NOT NULL DEFAULT 'America/Los_Angeles');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"role" TEXT NOT NULL CHECK ("role" IN ('PATIENT','STAFF')),"plan" TEXT NOT NULL DEFAULT 'Blue Horizon',"clinicId" TEXT REFERENCES "Clinic"("id"));
CREATE TABLE "Slot" ("id" TEXT PRIMARY KEY,"clinicId" TEXT NOT NULL REFERENCES "Clinic"("id"),"service" TEXT NOT NULL,"provider" TEXT NOT NULL,"start" TIMESTAMP(3) NOT NULL,"end" TIMESTAMP(3) NOT NULL,"price" INTEGER NOT NULL CHECK ("price">=0),"plans" TEXT[] NOT NULL,"status" TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK ("status" IN ('AVAILABLE','HELD','BOOKED')), CHECK ("end">"start"));
CREATE TABLE "Booking" ("id" TEXT PRIMARY KEY,"patientId" TEXT NOT NULL REFERENCES "User"("id"),"slotId" TEXT NOT NULL REFERENCES "Slot"("id"),"status" TEXT NOT NULL DEFAULT 'CONFIRMED' CHECK ("status" IN ('CONFIRMED','CANCELLED','RESCHEDULED')),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Waitlist" ("id" TEXT PRIMARY KEY,"patientId" TEXT NOT NULL REFERENCES "User"("id"),"service" TEXT NOT NULL,"plan" TEXT NOT NULL,"city" TEXT NOT NULL DEFAULT '',"clinicIds" TEXT[] NOT NULL,"maxPrice" INTEGER NOT NULL CHECK ("maxPrice">=0),"earliest" TIMESTAMP(3) NOT NULL,"latest" TIMESTAMP(3) NOT NULL,"startHour" INTEGER NOT NULL DEFAULT 0,"endHour" INTEGER NOT NULL DEFAULT 24,"weekdays" INTEGER[] NOT NULL,"bookingId" TEXT REFERENCES "Booking"("id"),"status" TEXT NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE','FULFILLED','WITHDRAWN')),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK ("latest">"earliest"),CHECK ("startHour">=0 AND "endHour"<=24 AND "endHour">"startHour"));
CREATE TABLE "Suggestion" ("id" TEXT PRIMARY KEY,"slotId" TEXT NOT NULL REFERENCES "Slot"("id"),"waitlistId" TEXT NOT NULL REFERENCES "Waitlist"("id"),"reasons" TEXT[] NOT NULL,UNIQUE("slotId","waitlistId"));
CREATE TABLE "Offer" ("id" TEXT PRIMARY KEY,"slotId" TEXT NOT NULL REFERENCES "Slot"("id"),"waitlistId" TEXT NOT NULL REFERENCES "Waitlist"("id"),"patientId" TEXT NOT NULL REFERENCES "User"("id"),"status" TEXT NOT NULL DEFAULT 'PENDING' CHECK ("status" IN ('PENDING','ACCEPTED','DECLINED','EXPIRED','REVOKED')),"reason" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"patientId" TEXT NOT NULL REFERENCES "User"("id"),"offerId" TEXT REFERENCES "Offer"("id"),"title" TEXT NOT NULL,"body" TEXT NOT NULL,"read" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Audit" ("id" TEXT PRIMARY KEY,"clinicId" TEXT NOT NULL REFERENCES "Clinic"("id"),"actor" TEXT NOT NULL,"action" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Slot_clinicId_start_idx" ON "Slot"("clinicId","start");
CREATE INDEX "Booking_patientId_status_idx" ON "Booking"("patientId","status");
CREATE UNIQUE INDEX "one_confirmed_booking_per_slot" ON "Booking"("slotId") WHERE "status"='CONFIRMED';
CREATE UNIQUE INDEX "one_pending_offer_per_slot" ON "Offer"("slotId") WHERE "status"='PENDING';
CREATE UNIQUE INDEX "one_active_waitlist_per_service" ON "Waitlist"("patientId","service") WHERE "status"='ACTIVE';
CREATE UNIQUE INDEX "one_notification_per_offer" ON "Notification"("offerId") WHERE "offerId" IS NOT NULL;
